import {hospitals} from './seed.js';
import {sampleStaff,samplePassword} from './sample-staff.js';
const $=s=>document.querySelector(s);let challenge=null,expectedRole;
function chooseDesk(role){expectedRole=role||undefined;document.querySelectorAll('[data-desk]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.desk===role)));$('#signin-title').textContent=role==='ems'?'Dispatcher sign-in':role==='hospital'?'ER Unit Coordinator sign-in':'Welcome back';$('#desk-entry-help').textContent=role==='ems'?'Open the EMS desk to send requests and see hospital acceptances.':role==='hospital'?'Open your assigned hospital inbox to review and accept EMS requests.':'Choose your role, then sign in with your staff details.';}
document.querySelectorAll('[data-desk]').forEach(b=>b.onclick=()=>chooseDesk(b.dataset.desk));
$('#requested-facility').innerHTML=hospitals.map(h=>`<option value="${h.id}">${h.name}</option>`).join('');
$('#sample-password').textContent='Public sample password: '+samplePassword;
$('#sample-accounts').innerHTML=sampleStaff.map((s,i)=>`<button type="button" class="sample-desk" data-example="${i}" data-testid="sample-${s.role==='hospital'?s.facilityId:s.role}"><span aria-hidden="true">${s.role==='ems'?'↗':s.role==='admin'?'⚙':'+'}</span><strong>${s.role==='ems'?'EMS desk':s.role==='admin'?'Administrator':s.facilityId==='maple'?'Maplewood hospital':'Riverside hospital'}</strong><small>${s.role==='hospital'?'Review & accept':'ems'===s.role?'Send & track requests':'Manage sample access'}</small></button>`).join('');
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{chooseDesk(sampleStaff[Number(b.dataset.example)].role==='admin'?null:sampleStaff[Number(b.dataset.example)].role);$('#email').value=sampleStaff[Number(b.dataset.example)].email;$('#password').value=samplePassword;document.querySelectorAll('[data-example]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#email').focus();});
async function post(path,input){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not complete this step.');return data;}
async function signIn(input){$('#login-error').textContent='';try{const r=await post('/api/auth/login',{...input,...(expectedRole?{expectedRole}:{})});if(r.mfa){challenge=r.mfa.challengeToken;$('#login-form').hidden=true;$('#mfa-form').hidden=false;return;}location.assign(r.actor.role==='admin'?'/staff.html':'/');}catch(e){$('#login-error').textContent=e.message;}}
$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await signIn({email:$('#email').value,password:$('#password').value});}finally{b.disabled=false;}};
$('#mfa-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await signIn({challengeToken:challenge,code:$('#mfa-code').value});}finally{e.submitter.disabled=false;}};
$('#register-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const r=await post('/api/auth/register',{name:$('#register-name').value,email:$('#register-email').value,password:$('#register-password').value,employeeNumber:$('#employee-number').value,requestedRole:$('#requested-role').value,facilityId:$('#requested-facility').value});$('#register-status').textContent=r.message;$('#register-password').value='';}catch(e){$('#register-status').textContent=e.message;}finally{e.submitter.disabled=false;}};
document.querySelectorAll('#login-form button,#register-form button').forEach(b=>b.disabled=true);
fetch('/api/auth/config').then(r=>{if(!r.ok)throw Error();document.querySelectorAll('#login-form button,#register-form button').forEach(b=>b.disabled=false);}).catch(()=>{$('#login-error').textContent='Sample staff setup is temporarily unavailable. Retry later; use your established offline backup process for urgent coordination.';});
